curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        if 'diego' in u.get('real_name','').lower() or 'alvarez' in u.get('real_name','').lower():
            print(json.dumps(u, indent=2))
else:
    print(json.dumps(data, indent=2))
"

curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=private_channel&limit=1000" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for c in data['channels']:
        purpose = c.get('purpose',{}).get('value','')
        if 'onboarding' in purpose.lower() or 'new hires' in purpose.lower():
            print(json.dumps(c, indent=2))
else:
    print(json.dumps(data, indent=2))
"
